"""UNet fixture family tests (synthetic, generated by make_unet_fixtures.py).

Covers: ONNX structure, cross-model diff semantics (stem+residual = added
nodes, UNet core fully matched), and PyTorch module-tree loading.
"""

import os
import subprocess
import sys

import pytest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FIXTURES = os.path.join(ROOT, "fixtures")
PT_DIR = os.path.join(FIXTURES, "pytorch")

from modeltoolbox.diff_engine import diff_models  # noqa: E402
from modeltoolbox.folding import find_common_groups  # noqa: E402
from modeltoolbox.layout import layout_diff_pair  # noqa: E402
from modeltoolbox.onnx_importer import load_onnx  # noqa: E402
from modeltoolbox.pytorch_importer import PyTorchImportSpec, load_pytorch_module  # noqa: E402


@pytest.fixture(scope="module", autouse=True)
def unet_fixtures():
    r = subprocess.run(
        [sys.executable, os.path.join(ROOT, "scripts", "make_unet_fixtures.py")],
        capture_output=True, text=True, cwd=ROOT)
    assert r.returncode == 0, f"fixture generation failed:\n{r.stdout}\n{r.stderr}"
    return FIXTURES


@pytest.fixture(scope="module")
def ir_a(unet_fixtures):
    return load_onnx(os.path.join(FIXTURES, "unet5_512.onnx"), "ua")


@pytest.fixture(scope="module")
def ir_b(unet_fixtures):
    return load_onnx(os.path.join(FIXTURES, "unet5_512_stem.onnx"), "ub")


# ---- ONNX structure ----

def test_unet_a_structure(ir_a):
    assert ir_a.inputs[0].shape == [1, 1, 512, 512]
    assert ir_a.outputs[0].shape == [1, 1, 512, 512]
    assert len(ir_a.nodes) >= 60
    ops = {n.op_type for n in ir_a.nodes}
    assert {"Conv", "MaxPool", "Resize", "Concat", "Relu"} <= ops
    # the residual Add only exists in the stem variant (model B)
    # bottleneck must exist at 1/32 resolution (32x32)
    shapes = [n.output_info[t].shape for n in ir_a.nodes
              for t in n.outputs if t in n.output_info and n.output_info[t].shape]
    spatial = {tuple(s[2:]) for s in shapes}
    assert (32, 32) in spatial and (512, 512) in spatial


def test_unet_b_is_superset(ir_a, ir_b):
    assert len(ir_b.nodes) > len(ir_a.nodes)
    ops = {n.op_type for n in ir_b.nodes}
    assert "Add" in ops  # residual join


# ---- diff semantics ----

def test_unet_core_matches_and_stem_is_added(ir_a, ir_b):
    d = diff_models(ir_a, ir_b)
    s = d.summary
    # the shared UNet core must be fully paired; exactly ONE node legitimately
    # changes its upstream connection (/inc/conv1 now consumes stem_act),
    # everything else is unchanged
    assert s["unchanged"] + s["connection_changed"] == len(ir_a.nodes)
    assert s["added"] == len(ir_b.nodes) - len(ir_a.nodes)
    assert s["removed"] == 0 and s["ambiguous"] == 0
    assert s["op_changed"] == 0 and s["shape_changed"] == 0 and s["attr_changed"] == 0
    conn = [nd for nd in d.node_diffs if nd.kind == "connection_changed"]
    assert len(conn) == 1 and conn[0].a_node_id == "/inc/conv1/Conv"
    added = [nd for nd in d.node_diffs if nd.kind == "added"]
    added_b_ids = {nd.b_node_id for nd in added}
    # the added nodes must be exactly the stem convs, their activation and
    # the residual Add
    assert any("stem_in" in x for x in added_b_ids)
    assert any("stem_out" in x for x in added_b_ids)
    assert any("stem_act" in x for x in added_b_ids)
    assert len(added) == len(ir_b.nodes) - len(ir_a.nodes)
    # field-level change on the added residual: none (it is purely new)
    assert all(nd.changes == [] for nd in added)


def test_unet_layout_pair_and_folding(ir_a, ir_b):
    from modeltoolbox.matcher import match_graphs
    match = match_graphs(ir_a, ir_b)
    la, lb = layout_diff_pair(ir_a, ir_b, match.matches)
    for m in match.matches:
        assert la.boxes[m.a_node_id].y == lb.boxes[m.b_node_id].y
    folding = find_common_groups(ir_a, ir_b, match.matches)
    # the dense matched core should form at least one fold group
    assert folding.groups, "UNet core should be foldable"
    g = max(folding.groups, key=lambda x: len(x.node_ids_a))
    assert len(g.node_ids_a) >= 20


# ---- PyTorch module tree ----

def test_pytorch_unet5_module_tree():
    res = load_pytorch_module(PyTorchImportSpec(
        project_path=PT_DIR, import_path="unet_models",
        class_name="UNet5", timeout_s=120))
    assert res.ok, res.error
    flat = {n["path"]: n for n in _flatten(res.module_tree)}
    for p in ["inc", "down1", "down2", "down3", "down4", "bottom",
              "up1", "up2", "up3", "up4", "head"]:
        assert p in flat, f"missing {p}"
    assert flat["down1.block"]["class_name"] == "DoubleConv"
    assert flat[""]["param_count"] == 0
    assert flat["head"]["param_count"] > 0
    assert sum(flat[p]["param_count"] for p in flat) > 10000


def test_pytorch_unet5_stem_module_tree():
    res = load_pytorch_module(PyTorchImportSpec(
        project_path=PT_DIR, import_path="unet_models",
        class_name="UNet5Stem", timeout_s=120))
    assert res.ok, res.error
    flat = {n["path"]: n for n in _flatten(res.module_tree)}
    assert {"stem_in", "stem_act", "unet", "stem_out"} <= set(flat)
    # nested UNet5 is visible under .unet
    assert flat["unet"]["class_name"] == "UNet5"
    assert "unet.down1" in flat
    # leaf rule collapses the whole UNet subtree
    res2 = load_pytorch_module(PyTorchImportSpec(
        project_path=PT_DIR, import_path="unet_models",
        class_name="UNet5Stem", timeout_s=120,
        leaf_rules=[{"path_pattern": "unet"}]))
    assert res2.ok
    flat2 = {n["path"]: n for n in _flatten(res2.module_tree)}
    assert flat2["unet"]["is_leaf"] is True
    assert "unet.down1" not in flat2  # subtree collapsed
    assert flat2["stem_in"]["is_leaf"] is False


def _flatten(tree):
    out = []

    def walk(n):
        item = dict(n)
        item.pop("children", None)
        out.append(item)
        for c in n.get("children", []) or []:
            walk(c)

    walk(tree)
    return out
